import React from 'react';
import PromotionItem from './PromotionItem';
import '../styles/PromotionSection.css';

const PromotionSection = () => {
    // Левый большой блок
    const leftPromotion = {
        img: `${process.env.PUBLIC_URL}/imgg/Group 518.png`,
        title: "Велика знижка на меблі для вітальні",
        description: "До -50% на всі меблі для вітальні"
    };

    // Правые товары
    const products = [
        {
            id: 1,
            title: "Темно-зелене крісло для відпочинку KELSO",
            img: `${process.env.PUBLIC_URL}/imgg/Rectangle 212.png`,
            rating: 4.5,
            price: 1840
        },
        {
            id: 2,
            title: "Декоративна наволочка VELVET",
            img: `${process.env.PUBLIC_URL}/imgg/Rectangle 212 (1).png`,
            rating: 4.8,
            price: 200
        },
        {
            id: 3,
            title: "Настільна лампа Mondex Leti 15x29 см",
            img: `${process.env.PUBLIC_URL}/imgg/Rectangle 212 (2).png`,
            rating: 4.2,
            price: 699
        },
        {
            id: 4,
            title: "Дерев'яний журнальний столик із символом синьої квітки життя",
            img: `${process.env.PUBLIC_URL}/imgg/Rectangle 212 (3).png`,
            rating: 4.7,
            price: 1250
        }
    ];

    return (
        <section className="promotion-section">
            <div className="promotion-left">
                <img src={leftPromotion.img} alt={leftPromotion.title} />
                <div className="promotion-left-content">
                    <h2>{leftPromotion.title}</h2>
                    <p>{leftPromotion.description}</p>
                    <a href="#" className="promotion-left-btn">Дивитися акцію</a>
                </div>
            </div>
            <div className="promotion-right">
                <div className="promotion-items">
                    {products.map(product => (
                        <PromotionItem key={product.id} item={product} />
                    ))}
                </div>
            </div>
        </section>
    );
};

export default PromotionSection;
